/*
 * The Clans board: sixty territories on an "odd-r" hex grid (odd rows
 * shifted half a hex right), in twelve regions of five, with four terrains
 * fifteen apiece. Lakes break some adjacencies. Generated by the map
 * script; the server and the client hold identical copies.
 */

export type Terrain = "GRASSLAND" | "FOREST" | "MOUNTAIN" | "STEPPE";

export type TerritoryInfo = {
  col: number;
  row: number;
  terrain: Terrain;
  /** Setup region: each gets one hut of every colour. */
  region: number;
  /** Territories reachable across a river; lakes are left out. */
  adjacent: number[];
};

